update public.cards c
set element_types = type_rows.element_types
from public.card_sets s, type_rows
where c.card_set_id = s.id
  and s.set_code = 'SV09'
  and s.language = 'FR'
  and split_part(c.collector_number, '/', 1) ~ '^[0-9]+$'
  and split_part(c.collector_number, '/', 1)::integer = type_rows.local_id;
